SELECT 'датчик «migration-table» ' || fact_gap($1, 'migration-table') || ': проверить нечем, и это не зелёное' AS detail WHERE NOT fact_fresh($1, 'migration-table') UNION ALL SELECT f.name || ' — заведена ' || f.detail || ', в модели не описана' AS detail FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'migration-table' AND NOT EXISTS (SELECT 1 FROM project_db_tables t WHERE t.project_id = f.project_id AND t.name = f.name) ORDER BY 1
